<?php
namespace App\Services\Automation;
use App\Models\{AutomationAction,AutomationExecution};use App\Services\NotificationMaterializationService;
final class AutomationActionExecutor{
 public function execute(AutomationAction $action,AutomationExecution $execution):array{$started=microtime(true);try{$message=(string)($action->configuration['payload']['message']??'Automation triggered');if($action->type!=='notification')throw new \RuntimeException('Unsupported action type.');$service=app(NotificationMaterializationService::class);foreach($execution->automation->organization->users()->where('status','active')->get() as $user)$service->createOnce($user,'automation.notification',"automation_execution:{$execution->id}:action:{$action->id}",['organization_id'=>$execution->organization_id,'actor_id'=>$execution->requested_by,'resource_type'=>'automation','resource_id'=>$execution->automation_id,'action_url'=>"/app/automations/{$execution->automation_id}",'title'=>$execution->automation->name,'message'=>$message,'severity'=>'warning','requires_action'=>false]);$result=['actionId'=>(string)$action->id,'success'=>true,'message'=>'Notification created','executedAt'=>now()->toISOString()];$this->log($execution,$action,'info',$result['message'],$result);return $result;}catch(\Throwable $e){$result=['actionId'=>(string)$action->id,'success'=>false,'message'=>$e->getMessage(),'executedAt'=>now()->toISOString()];$this->log($execution,$action,'error',$result['message'],[]);return $result+['durationMs'=>(int)((microtime(true)-$started)*1000)];}}
 private function log(AutomationExecution $e,AutomationAction $a,string $level,string $message,array $context):void{$e->logs()->create(['automation_action_id'=>$a->id,'level'=>$level,'message'=>$message,'context'=>$this->redact($context),'executed_at'=>now()]);}
 private function redact(array $data):array{foreach($data as $k=>$v){if(preg_match('/token|password|secret|key/i',(string)$k))$data[$k]='[REDACTED]';elseif(is_array($v))$data[$k]=$this->redact($v);}return $data;}
}
